"""Regenerate models, translations, recipes and the empty test arena; biological PNGs are generated by Gradle."""
import gzip
import json
import struct
import zlib
from pathlib import Path

root = Path(__file__).resolve().parents[1] / 'src/main/resources'
assets = root / 'assets/mobvats'
data = root / 'data/mobvats'

def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2) + '\n', encoding='utf-8')

textures = dict(vat_casing=None, vat_glass='glass', vat_controller='observer_front',
                vat_harness='heavy_core', vat_drain='hopper_top', vat_head=None, vat_flesh=None,
                item_port='dispenser_front', fluid_port='dropper_front', tool_port='piston_top')
lang = {
    'itemGroup.mobvats': 'MobVats', 'item.mobvats.syringe': 'Syringe', 'item.mobvats.essence': 'Cow Essence',
    'message.mobvats.bottle': 'A glass bottle is required to collect essence.',
    'message.mobvats.formed': 'Vat formed.',
    'message.mobvats.unformed': 'Vat unformed. Sneak and right-click for validation details.',
    'multiblock.mobvats.invalid_position': '%s is not valid at %s.',
    'multiblock.mobvats.one_specimen': 'Exactly one of each required: controllers %s, harnesses %s, drains %s, heads %s.',
    'multiblock.mobvats.encoded_head': 'Place a cow-encoded head directly below the harness.',
    'multiblock.mobvats.flesh_column': 'Contiguous flesh must connect the encoded head to the drain.',
    'multiblock.mobvats.substrate': 'Insufficient cow substrate: %s head/flesh blocks; need %s.',
    'multiblock.mobvats.extra_flesh': 'Flesh outside the specimen column: %s total flesh, %s in the column. Remove this extra flesh.',
    'multiblock.mobvats.room': 'Insufficient cow room: interior %s x %s x %s; need %s x %s x %s (X,Y,Z).',
    'multiblock.mobvats.drain': 'Misaligned drain: expected at %s below the specimen, found drain at %s. Expected position contains %s.',
}
for name, texture in textures.items():
    lang['block.mobvats.' + name] = name.replace('_', ' ').title()
    write(assets / f'blockstates/{name}.json', {'variants': {'': {'model': 'mobvats:block/' + name}}})
    if name == 'vat_head':
        write(assets / f'blockstates/{name}.json', {'variants': {
            f'facing={facing}': {'model': 'mobvats:block/vat_head', 'y': angle}
            for facing, angle in (('north', 0), ('east', 90), ('south', 180), ('west', 270))}})
    model = {'parent': 'minecraft:block/cube_all', 'textures': {'all': 'minecraft:block/' + texture if texture else 'mobvats:blocks/' + name}}
    if name == 'vat_casing':
        model['textures']['all'] = 'mobvats:blocks/vat_casing_face'
    if name == 'vat_head':
        # Historical model: face on north, head texture on the other five faces.
        model = {'parent': 'minecraft:block/cube', 'textures': {side: 'mobvats:blocks/vat_head'
            for side in ('particle', 'down', 'up', 'east', 'west', 'south')}}
        model['textures']['north'] = 'mobvats:blocks/vat_face'
    write(assets / f'models/block/{name}.json', model)
    write(assets / f'models/item/{name}.json', {'parent': 'mobvats:block/' + name})
    write(data / f'loot_table/blocks/{name}.json', {'type': 'minecraft:block', 'pools': [{'rolls': 1,
          'entries': [{'type': 'minecraft:item', 'name': 'mobvats:' + name}], 'conditions': [{'condition': 'minecraft:survives_explosion'}]}]})
write(assets / 'models/block/hidden.json', {'textures': {'particle': 'mobvats:blocks/vat_head'}, 'elements': []})
write(assets / 'models/block/formed_glass_material.json', {
    'parent': 'minecraft:block/cube_all', 'render_type': 'minecraft:translucent',
    'textures': {'all': 'mobvats:blocks/tank_surface', 'particle': 'mobvats:blocks/tank_rim'}})
write(assets / 'models/block/casing_material.json', {
    'parent': 'minecraft:block/cube', 'render_type': 'minecraft:solid',
    'textures': {side: 'mobvats:blocks/' + texture for side, texture in {
        'particle': 'vat_casing_face', 'down': 'vat_casing_face', 'up': 'vat_casing_edge',
        'north': 'vat_casing_inner', 'south': 'vat_casing_face',
        'east': 'vat_casing_face', 'west': 'vat_casing_face'}.items()}})

# Uniform procedural glass materials, not recovered historical artwork. No pixel-cell borders.
def pixel_png(path, pixel):
    def chunk(kind, payload):
        return struct.pack('>I', len(payload)) + kind + payload + struct.pack('>I', zlib.crc32(kind + payload))
    pixels = b''.join(b'\0' + b''.join(bytes(pixel(x, y)) for x in range(16)) for y in range(16))
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(b'\x89PNG\r\n\x1a\n'
        + chunk(b'IHDR', struct.pack('>IIBBBBB', 16, 16, 8, 6, 0, 0, 0))
        + chunk(b'IDAT', zlib.compress(pixels)) + chunk(b'IEND', b''))

def uniform_png(path, rgba):
    pixel_png(path, lambda x, y: rgba)

# Native MobVats pixels: subdued blue-steel, sparse fasteners, no borrowed shell art.
def casing_face(x, y):
    palette = ((88, 103, 111), (91, 106, 114), (94, 109, 116))
    color = palette[(x * 7 + y * 11 + x * y) % 3]
    if y == 0 or x == 0:
        color = (119, 136, 144)
    elif y == 15 or x == 15:
        color = (56, 71, 81)
    if (x, y) in ((2, 2), (13, 13)):
        color = (43, 56, 65)
    elif (x, y) in ((2, 1), (13, 12)):
        color = (151, 167, 172)
    if y == 11 and 6 <= x <= 9:
        color = (88, 104, 86)  # Restrained laboratory olive marking.
    return (*color, 255)

def casing_edge(x, y):
    color = (48, 65, 77)
    if y == 0:
        color = (153, 181, 192)
    elif y == 1:
        color = (86, 113, 128)
    elif y >= 14:
        color = (27, 40, 51)
    elif y == 7 and x in (3, 12):
        color = (102, 125, 135)
    return (*color, 255)

def casing_inner(x, y):
    color = (42, 55, 63) if (x + y * 3) % 7 else (46, 60, 67)
    if y in (4, 12) and 3 <= x <= 12:
        color = (52, 67, 74)
    return (*color, 255)

for name, painter in (('face', casing_face), ('edge', casing_edge), ('inner', casing_inner)):
    pixel_png(assets / f'textures/blocks/vat_casing_{name}.png', painter)

uniform_png(assets / 'textures/blocks/tank_surface.png', (190, 224, 235, 18))
uniform_png(assets / 'textures/blocks/tank_rim.png', (175, 213, 229, 180))
# Minecraft's default atlas discovers singular block/item folders, not historical blocks/items.
write(root / 'assets/minecraft/atlases/blocks.json', {'sources': [
    {'type': 'minecraft:single', 'resource': 'mobvats:' + texture}
    for texture in ('blocks/vat_head', 'blocks/vat_face', 'blocks/vat_flesh',
                    'items/item_syringe', 'items/item_essence', 'blocks/tank_surface', 'blocks/tank_rim',
                    'blocks/vat_casing_face', 'blocks/vat_casing_edge', 'blocks/vat_casing_inner')]})
write(assets / 'lang/en_us.json', lang)
for name in ('syringe', 'essence'):
    write(assets / f'models/item/{name}.json', {'parent': 'minecraft:item/generated', 'textures': {'layer0': 'mobvats:items/item_' + name}})
write(root / 'pack.mcmeta', {'pack': {'pack_format': 34, 'description': 'MobVats resources'}})
recipes = {
    'syringe': ['minecraft:iron_ingot', 'minecraft:glass_bottle', 'minecraft:bone'],
    'vat_casing': ['minecraft:iron_ingot', 'minecraft:glass'],
    'vat_glass': ['mobvats:vat_casing', 'minecraft:glass'],
    'vat_controller': ['mobvats:vat_casing', 'minecraft:redstone'],
    'vat_harness': ['mobvats:vat_casing', 'minecraft:chain'],
    'vat_drain': ['mobvats:vat_casing', 'minecraft:hopper'],
    'vat_flesh': ['minecraft:rotten_flesh', 'minecraft:slime_ball'],
    'vat_head': ['mobvats:vat_flesh', 'minecraft:iron_ingot'],
}
for name, ingredients in recipes.items():
    write(data / f'recipe/{name}.json', {'type': 'minecraft:crafting_shapeless', 'ingredients': [{'item': i} for i in ingredients],
          'result': {'id': 'mobvats:' + name, 'count': 4 if name in ('vat_casing', 'vat_glass') else 1}})

# Minimal NBT structure using only standard library; no external authoring dependency.
def string(value):
    encoded = value.encode('utf-8')
    return struct.pack('>H', len(encoded)) + encoded
def tag(kind, name, payload):
    return bytes([kind]) + string(name) + payload
structure = (tag(3, 'DataVersion', struct.pack('>i', 3955))
    + tag(9, 'size', bytes([3]) + struct.pack('>iiii', 3, 12, 8, 12))
    + tag(9, 'palette', bytes([10]) + struct.pack('>i', 1) + tag(8, 'Name', string('minecraft:air')) + b'\0')
    + tag(9, 'blocks', bytes([10]) + struct.pack('>i', 0))
    + tag(9, 'entities', bytes([10]) + struct.pack('>i', 0)) + b'\0')
path = data / 'structure/empty.nbt'
path.parent.mkdir(parents=True, exist_ok=True)
payload = tag(10, '', structure)
# Preserve an equivalent existing arena across Python gzip-header version differences.
if not path.exists() or gzip.decompress(path.read_bytes()) != payload:
    path.write_bytes(gzip.compress(payload, mtime=0))

# Provisional one-block port recipes; direction is runtime state, never a craft variant.
for kind, ingredient in (('item', 'minecraft:hopper'), ('fluid', 'minecraft:bucket'), ('tool', 'minecraft:piston')):
    write(data / f'recipe/{kind}_port.json', {'type': 'minecraft:crafting_shapeless',
        'ingredients': [{'item': 'mobvats:vat_casing'}, {'item': 'minecraft:iron_ingot'}, {'item': ingredient}],
        'result': {'id': f'mobvats:{kind}_port', 'count': 1}})
